import {SIGMAS,LABELS,confidence,updateValue,trainingSteps,bin} from './engine.mjs?v=20261008r3';

const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=n=>Number(n).toFixed(3), signed=n=>(n>=0?'+':'')+f(n);
const actionNames=['Scan again','Drill','Move on'];
let iterator=trainingSteps(), event=null, updates=0;

export function resetLab(){iterator=trainingSteps();event=null;updates=0;}
export function advanceLab(count=1){for(let i=0;i<count;i++){const step=iterator.next();if(step.done)break;event=step.value;updates++;}}
function codeBlock(fn,caption){return `<details class="source-code"><summary>${caption} <span>JavaScript · actual engine function</span></summary><pre tabindex="0"><code>${esc(fn.toString())}</code></pre><a href="https://github.com/ditto-d/fuse-decide-fight/blob/main/dist/engine.mjs" target="_blank" rel="noopener">Open engine source ↗</a></details>`;}

export function pipeline(){return `<div class="pipeline" aria-label="From sensor evidence to a learned action"><div><small>01 · OBSERVE</small><strong>Noisy signals</strong><span>Three simulated instruments</span></div><b aria-hidden="true">→</b><div><small>02 · FUSE</small><strong>Water estimate</strong><span>Bayesian update we wrote</span></div><b aria-hidden="true">→</b><div><small>03 · DECIDE</small><strong>Scan, drill, or move</strong><span>Action values learned from reward</span></div></div>`;}

export function fusionLab(readings){
  const prior=Math.log(.3/.7);
  const contributions=SIGMAS.map((s,i)=>readings.reduce((total,scan)=>total+2*scan[i]/s**2,0));
  const total=prior+contributions.reduce((a,b)=>a+b,0),p=confidence(readings);
  return `<section class="panel section-gap"><div class="panel-head"><div><div class="eyebrow">EVIDENCE LAB</div><h3>Where did that percentage come from?</h3></div><span class="chip">${readings.length} SCAN${readings.length===1?'':'S'}</span></div><div class="pad"><p>Each number is a synthetic signal: positive supports wet, negative supports dry. More reliable sensors contribute more evidence. We add evidence to the prior in <strong>log-odds</strong>, then convert back to a probability.</p><div class="table-wrap"><table><thead><tr><th>Instrument</th><th>Latest signal</th><th>Noise SD</th><th>Evidence from all scans</th></tr></thead><tbody>${LABELS.map((name,i)=>`<tr><td>${name}</td><td class="mono">${signed(readings.at(-1)[i])}</td><td class="mono">${SIGMAS[i].toFixed(2)}</td><td class="mono ${contributions[i]>0?'check':''}">${signed(contributions[i])}</td></tr>`).join('')}</tbody></table></div><div class="equation">Prior ${f(prior)} ${contributions.map(signed).join(' ')} = ${f(total)} log-odds <strong>→ ${(p*100).toFixed(1)}% wet</strong></div><p class="compact">Per reading: evidence = 2 × signal ÷ noise variance. The displayed 61 / 27 / 12 weights are relative inverse variances; we do not average the three percentages. Assumption: independent Gaussian noise, means +1 when wet and −1 when dry.</p>${codeBlock(confidence,'Show the fusion code')}</div></section>`;
}

export function learningLab(focused=false){const e=event;return `<section class="panel section-gap"><div class="panel-head"><div><div class="eyebrow">LIVE CODE LAB</div><h3>Watch one number in the Q-table change.</h3></div><div class="toolbar"><span class="chip">${updates.toLocaleString()} UPDATE${updates===1?'':'S'}</span><button class="small ghost" data-do="lab-focus">${focused?'Exit focus':'Focus lab'}</button></div></div><div class="pad"><p>This separate lab starts from 486 zeros. Each click executes real training actions using the same function as Train Rove. Price stays at 0.45 here; it does not change the competition agent.</p><div class="toolbar"><button class="primary" data-do="lab-step">Next training action</button><button data-do="lab-batch">Run 25 actions</button><button class="ghost" data-do="lab-reset">Reset table</button></div><div class="lab-layout"><div class="lab-results">${e?`<div class="transition-grid section-gap"><div><small>STATE BEFORE</small><strong>${(e.p*100).toFixed(1)}% wet</strong><span>Bin ${bin(e.p)+1} of 18 · ${e.rescans} extra scans</span></div><div><small>ACTION</small><strong>${actionNames[e.action]}</strong><span>${e.exploratory?'Exploration draw':'Greedy choice'} · ε = ${e.epsilon.toFixed(3)}</span></div><div><small>REWARD</small><strong>${signed(e.reward)}</strong><span>${e.action===0?'Paid for another scan':e.action===2?'Paid to move; truth stays hidden':e.wet?'Water found: 10 − 9 × 0.45':'Dry hole: 0 − 9 × 0.45'}</span></div><div><small>${e.terminal?'EPISODE ENDS':'NEXT OBSERVATION'}</small><strong>${e.terminal?'No future value':(e.nextP*100).toFixed(1)+'% wet'}</strong><span>Training site ${e.episode.toLocaleString()}</span></div></div><div class="update-proof"><div><span>Old Q</span><strong>${f(e.before)}</strong></div><b>+</b><div><span>Learning rate</span><strong>0.12</strong></div><b>×</b><div><span>Target − old Q</span><strong>(${f(e.target)} − ${f(e.before)})</strong></div><b>=</b><div class="updated"><span>New Q</span><strong>${f(e.after)}</strong></div></div><p class="compact">Target = reward ${f(e.reward)} + future value ${f(e.future)} = ${f(e.target)}. Future value is the best available Q at the next state; it is zero after drill or move. Displayed values are rounded.</p><div class="q-values">${e.row.map((value,i)=>`<div class="${i===e.action?'changed':''}"><span>${actionNames[i]}</span><strong>${f(value)}</strong>${i===e.action?'<small>UPDATED CELL</small>':'<small>SAME STATE</small>'}</div>`).join('')}</div><p class="compact">Q-values are expected reward, not probabilities. One experience moves one value a little; thousands of experiences build the policy.</p>`:'<div class="lab-empty"><span class="mono">Q[state][action] = 0</span><h2>Predict before you click.</h2><p>A dry drill returns −4.05 reward units. What should its first Q update be with a learning rate of 0.12?</p></div>'}</div><div class="lab-code">${codeBlock(updateValue,'Show the Q-learning update')}${codeBlock(trainingSteps,'Show the training loop')}</div></div></div></section>`;}

export function realism(){return `<details class="help model-notes"><summary>What is realistic and what is simplified?</summary><div class="help-grid"><div><h3>The engineering problem</h3><p>Measurements contain noise. Additional observations cost resources. Decisions depend on uncertainty. A policy can fail when the sensor model changes. These are the ideas this workshop lets you test.</p><p>Real Mars rovers use imaging, spectroscopy and rock sampling to study geology. Our three channels are inspired by instruments, but their signals are dimensionless synthetic numbers, not calibrated scientific measurements.</p></div><div><h3>The teaching model</h3><p>“Liters” is a fictional resource score. This rover does not model extracting liquid water on Mars. Battery is a 100-unit action budget; terrain, travel distance, communication delay, extraction physics and hardware failures are omitted. The route is fixed.</p><p>Rove learns a per-site policy from confidence and scan count. Remaining battery is checked for legal actions, but is not part of its learned state. A more realistic planner would include it, along with time, terrain and uncertainty in the sensors themselves.</p></div></div><p><strong>3D rover:</strong> NASA/JPL’s Perseverance model on an illustrated Mars surface. Scan, arm and wheel animations are accelerated teaching visuals. They do not reproduce actual mission operations. <a href="./assets/CREDITS.md" target="_blank" rel="noopener">Visual credits ↗</a></p><p>Reference: <a href="https://science.nasa.gov/mission/mars-2020-perseverance/science-instruments/" target="_blank" rel="noopener">NASA’s Perseverance science instruments ↗</a> · <a href="https://www.incompleteideas.net/book/bookdraft2018mar21.pdf" target="_blank" rel="noopener">Sutton and Barto, Reinforcement Learning ↗</a></p></details>`;}

export function cue(stage){const cues=[
 ['04–14 min','Predict → scan → explain','Ask which sensor to trust. Show the raw evidence, add one scan, then reveal truth. Have students explain why an additional scan can lower confidence. Demo seed 3105 is separate from the challenge.'],
 ['14–27 min','Define reward → update one cell → train','Name state, action and reward. Step the live code lab. Ask students to calculate the update. Train Rove and reveal checkpoints deliberately. Change battery price, predict, then retrain.'],
 ['27–33 min','Inspect → compare → question','Read one policy row. Compare Rove with the hand-tuned rule across 300 missions. Ask what is missing from the state and why a learned policy need not win.'],
 ['33–47 min','Predict → play → defend a decision','Give two minutes for rules, three for a first attempt, then discuss and replay. Collect first-attempt scores separately from replays. A game score is an observation, not proof of superiority.'],
 ['47–53 min','Predict failure → test → repair','Ask whether more sensors solve shared bias. Start the storm. Compare retraining with subtracting a known bias. Retraining the policy does not calibrate the sensor probability.']
];const [time,title,text]=cues[stage];return `<details class="presenter-cue"><summary><span>FACILITATOR CUE · ${time}</span>${title}</summary><p>${text}</p><a href="./script.html" target="_blank" rel="noopener">Open the full 60-minute script ↗</a></details>`;}
